#!/usr/bin/env tsx
/**
 * Azure DevOps PR Creator
 *
 * Usage:
 *   tsx .agents/scripts/create-pr.ts [options]
 *
 * Options:
 *   --title <title>       PR title (default: last commit message)
 *   --description <desc>    PR description (default: auto-generated by an agent from the branch diff)
 *   --source <branch>     Source branch (default: current branch)
 *   --target <branch>     Target branch (default: main)
 *   --draft               Create as draft PR
 *   --push                Push source branch before creating PR
 *   --no-push             Skip push even if branch is unpushed
 */

import { spawnSync } from "node:child_process";
import {
  readFileSync,
  existsSync,
  writeFileSync,
  rmSync,
  mkdtempSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";

// ── Colored logging ─────────────────────────────────────────
const c = {
  red: "\x1b[0;31m",
  green: "\x1b[0;32m",
  yellow: "\x1b[1;33m",
  cyan: "\x1b[0;36m",
  reset: "\x1b[0m",
};
const info = (msg: string) => console.log(`${c.cyan}[INFO]${c.reset} ${msg}`);
const warn = (msg: string) => console.log(`${c.yellow}[WARN]${c.reset} ${msg}`);
const success = (msg: string) =>
  console.log(`${c.green}[OK]${c.reset}   ${msg}`);
const fail = (msg: string): never => {
  console.error(`${c.red}[ERROR]${c.reset} ${msg}`);
  process.exit(1);
};

// ── Load .env from script directory ─────────────────────────
const scriptDir = dirname(fileURLToPath(import.meta.url));
const envPath = join(scriptDir, ".env");
if (existsSync(envPath)) {
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const m = line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*)\s*$/i);
    if (!m) continue;
    const [, k, rawV] = m;
    const v = rawV.replace(/^["']|["']$/g, "");
    if (!(k in process.env)) process.env[k] = v;
  }
}

// ── Required env vars ────────────────────────────────────────
const requireEnv = (name: string): string =>
  process.env[name] ?? (fail(`Set ${name}`) as never);

const ADO_ORG = requireEnv("ADO_ORG");
const ADO_PROJECT = requireEnv("ADO_PROJECT");
const ADO_REPO = requireEnv("ADO_REPO");
const ADO_PAT = requireEnv("ADO_PAT");

const ADO_BASE = `https://dev.azure.com/${ADO_ORG}/${encodeURIComponent(ADO_PROJECT)}/_apis`;
const AUTH = `Basic ${Buffer.from(`:${ADO_PAT}`).toString("base64")}`;

// ── Arg parsing ──────────────────────────────────────────────
const args = process.argv.slice(2);
const getArg = (flag: string) => {
  const idx = args.indexOf(flag);
  return idx !== -1 && idx + 1 < args.length ? args[idx + 1] : undefined;
};
const hasFlag = (flag: string) => args.includes(flag);

const titleArg = getArg("--title");
const descriptionArg = getArg("--description");
const sourceArg = getArg("--source");
const targetArg = getArg("--target");
const isDraft = hasFlag("--draft");
const shouldPush = hasFlag("--push");
const noPush = hasFlag("--no-push");

// ── Git helpers ──────────────────────────────────────────────
function git(args: string[]): string {
  const result = spawnSync("git", args, { encoding: "utf8" });
  if (result.status !== 0) {
    fail(`git ${args.join(" ")} failed:\n${result.stderr}`);
  }
  return result.stdout.trim();
}

function getCurrentBranch(): string {
  return git(["rev-parse", "--abbrev-ref", "HEAD"]);
}

function getLastCommitMessage(): string {
  return git(["log", "-1", "--pretty=%s"]);
}

function branchHasRemote(branch: string): boolean {
  try {
    git(["rev-parse", "--abbrev-ref", `${branch}@{upstream}`]);
    return true;
  } catch {
    return false;
  }
}

function aheadOfOrigin(branch: string): number {
  if (!branchHasRemote(branch)) return 0;
  const aheadBehind = git([
    "rev-list",
    "--left-right",
    "--count",
    `${branch}...${branch}@{upstream}`,
  ]);
  // Output: "<ahead>\t<behind>"
  const [ahead] = aheadBehind.split("\t").map(Number);
  return ahead || 0;
}

// Like git() but returns null instead of killing the process on failure.
function gitSafe(args: string[]): string | null {
  const result = spawnSync("git", args, { encoding: "utf8" });
  return result.status === 0 ? result.stdout.trim() : null;
}

// ── PR description generation (agent) ───────────────────────
const MAX_DIFF_BYTES = 120_000;

function stripAnsi(s: string): string {
  return s.replace(/\x1b\[[0-9;]*m/g, "");
}

function buildChangeSummary(
  title: string,
  source: string,
  target: string,
): string {
  const mergeBase = gitSafe(["merge-base", target, source]);
  const range = mergeBase ? `${mergeBase}...${source}` : `${target}..${source}`;
  const commits =
    gitSafe(["log", "--oneline", "--no-merges", `${target}..${source}`]) ??
    "(no commits listed)";
  const stat = gitSafe(["diff", "--stat", range]) ?? "";
  let diff = gitSafe(["diff", range]) ?? "";
  if (diff.length > MAX_DIFF_BYTES) {
    diff = `${diff.slice(0, MAX_DIFF_BYTES)}\n\n(… diff truncated — exceeds ${MAX_DIFF_BYTES} bytes …)`;
  }

  return [
    "# PR Context",
    "",
    `Title: ${title}`,
    `Branch: ${source} → ${target}`,
    "",
    "## Commits",
    commits,
    "",
    "## Changed files",
    stat,
    "",
    "## Diff",
    diff,
  ].join("\n");
}

function generateDescription(context: string): string | null {
  info("Spawning agent to analyze branch changes...");
  const repoRoot = git(["rev-parse", "--show-toplevel"]);
  const dir = mkdtempSync(join(tmpdir(), "pr-desc-"));
  const file = join(dir, "changes.md");
  try {
    writeFileSync(file, context);
    const prompt = `You are creating a pull request description. The attached file contains the PR context, commits, and code diff for the branch being merged.

Based ONLY on that information, write a PR description that EXACTLY follows this template:

# SearchPoint PR

## What does this PR solve?

(this is to ensure you understand what task you are working)

## How does this PR solve the problem?

(this is to ensure you understand what changes you implement)

## How to test this PR?

1. (Step 1...)
2. (Step 2...)
3. Check x to verify y

Guidelines:
- Replace the parenthetical guidance with concrete content grounded in the diff.
- Keep it SHORT and concise — no long paragraphs, no verbose detail.
- "What does this PR solve?" — the problem/feature in 1-2 short sentences.
- "How does this PR solve the problem?" — the key changes in 1-3 short bullets or a brief sentence.
- "How to test this PR?" — 1-3 concrete steps max, keep each step short.
- Output ONLY the markdown description. No preamble, no code fences.`;

    const result = spawnSync(
      "opencode",
      [
        "run",
        prompt,
        "--dir",
        repoRoot,
        "-f",
        file,
        "-m",
        "opencode-go/deepseek-v4-flash",
      ],
      {
        encoding: "utf8",
        timeout: 10 * 60 * 1000,
        maxBuffer: 5 * 1024 * 1024,
      },
    );
    if (result.error) {
      warn(
        `Agent failed: ${result.error.message}\n  stderr: ${result.stderr?.slice(0, 300)}`,
      );
      return null;
    }
    if (result.status !== 0) {
      warn(
        `Agent exited with code ${result.status}\n  stderr: ${result.stderr?.slice(0, 300)}`,
      );
      return null;
    }
    const out = stripAnsi(result.stdout).trim();
    if (!out) {
      warn(
        `Agent returned empty stdout\n  stderr: ${result.stderr?.slice(0, 300)}`,
      );
      return null;
    }
    return out;
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// ── HTTP helpers ─────────────────────────────────────────────
async function ado<T = unknown>(
  path: string,
  init: RequestInit = {},
): Promise<T> {
  const url = `${ADO_BASE}${path}`;
  const res = await fetch(url, {
    ...init,
    headers: {
      Authorization: AUTH,
      "Content-Type": "application/json",
      ...(init.headers ?? {}),
    },
  });
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    fail(`${init.method ?? "GET"} ${url} \u2192 ${res.status}\n${body}`);
  }
  return res.json() as Promise<T>;
}

// Like ado() but returns null instead of killing the process on failure.
async function tryFetch<T = unknown>(
  path: string,
  init: RequestInit = {},
): Promise<T | null> {
  try {
    const url = `${ADO_BASE}${path}`;
    const res = await fetch(url, {
      ...init,
      headers: {
        Authorization: AUTH,
        ...(init.headers ?? {}),
      },
    });
    if (!res.ok) return null;
    return (await res.json()) as T;
  } catch {
    return null;
  }
}

// ── Work item helpers ────────────────────────────────────────
interface WorkItem {
  id: number;
  fields: Record<string, string>;
}

function extractWorkItemId(branch: string): number | null {
  const m = branch.match(/(\d+)(?:\D*)$/);
  return m ? Number(m[1]) : null;
}

function az(args: string[]): { ok: boolean; stdout: string; stderr: string } {
  const result = spawnSync("az", args, { encoding: "utf8" });
  return {
    ok: result.status === 0,
    stdout: result.stdout.trim(),
    stderr: result.stderr.trim(),
  };
}

async function fetchWorkItemTitle(id: number): Promise<string | null> {
  // 1. Try PAT-based REST API
  const item = await tryFetch<WorkItem>(`/wit/workitems/${id}?api-version=7.1`);
  if (item) {
    const title = item.fields["System.Title"];
    const type = item.fields["System.WorkItemType"];
    if (title) return `${type} ${id}: ${title}`;
  }

  // 2. Fallback to `az` CLI (requires `az login` + `az devops login`)
  const { ok, stdout, stderr } = az([
    "boards",
    "work-item",
    "show",
    "--id",
    String(id),
    "--org",
    `https://dev.azure.com/${ADO_ORG}`,
    "--output",
    "json",
  ]);
  if (!ok) {
    if (stderr.includes("az login") || stderr.includes("authentication")) {
      warn(
        `\`az\` is not authenticated — run: az login && az devops login --organization https://dev.azure.com/${ADO_ORG}`,
      );
    }
    return null;
  }
  try {
    const parsed = JSON.parse(stdout);
    const title = parsed.fields?.["System.Title"];
    const type = parsed.fields?.["System.WorkItemType"];
    if (title) return `${type} ${id}: ${title}`;
  } catch {
    // ignore parse errors
  }
  return null;
}

// ── Main ─────────────────────────────────────────────────────
const sourceBranch = sourceArg ?? getCurrentBranch();
const targetBranch = targetArg ?? "main";

if (sourceBranch === targetBranch) {
  fail(
    `Source branch (${sourceBranch}) cannot be the same as target branch (${targetBranch})`,
  );
}

// Resolve title: explicit arg > work item from branch > last commit
async function resolveTitle(): Promise<string> {
  if (titleArg) return titleArg;

  const workItemId = extractWorkItemId(sourceBranch);
  if (workItemId) {
    info(`Looking up work item ${workItemId}...`);
    const workItemTitle = await fetchWorkItemTitle(workItemId);
    if (workItemTitle) {
      success(`Found: ${workItemTitle}`);
      return workItemTitle;
    }
    warn(
      `Work item ${workItemId} not found or inaccessible — falling back to last commit message`,
    );
  } else {
    warn(
      `No work item ID found in branch "${sourceBranch}" — using last commit message`,
    );
  }

  return getLastCommitMessage();
}

const title = await resolveTitle();

let description = descriptionArg ?? "";
if (!description) {
  info("No description provided — generating from branch diff...");
  const context = buildChangeSummary(title, sourceBranch, targetBranch);
  const generated = generateDescription(context);
  info(
    `Agent returned: ${generated ? `"${generated.slice(0, 60)}..."` : "null"}`,
  );
  if (generated?.trim()) {
    description = generated;
    success("PR description generated by agent");
  } else {
    warn("Agent returned empty — cannot create PR without a description");
  }
}

// ADO rejects descriptions longer than 4000 characters
const MAX_DESCRIPTION_CHARS = 4000;
if (description.length > MAX_DESCRIPTION_CHARS) {
  warn(
    `Description is ${description.length} chars — truncating to ${MAX_DESCRIPTION_CHARS} (ADO limit)`,
  );
  description = description.slice(0, MAX_DESCRIPTION_CHARS);
}

if (!description.trim()) {
  fail(
    "PR description is empty — aborting. Pass --description or fix the agent generation.",
  );
}

info(`Source: ${sourceBranch} \u2192 Target: ${targetBranch}`);
info(`Title: ${title}`);
console.log(
  `\n${c.cyan}── PR description ───────────────────────────${c.reset}`,
);
console.log(description || c.yellow + "(empty)" + c.reset);
console.log(
  `${c.cyan}────────────────────────────────────────────────${c.reset}\n`,
);

// ── Push if needed ───────────────────────────────────────────
const ahead = aheadOfOrigin(sourceBranch);
if (ahead > 0) {
  if (noPush) {
    warn(`${ahead} unpushed commit(s) — proceeding without push (--no-push)`);
  } else {
    info(`Pushing ${ahead} commit(s) to origin...`);
    git(["push", "-u", "origin", sourceBranch]);
    success("Branch pushed");
  }
} else if (shouldPush) {
  info("Pushing branch...");
  git(["push", "-u", "origin", sourceBranch]);
  success("Branch pushed");
} else {
  info("Branch is up to date with origin");
}

// ── Create PR ────────────────────────────────────────────────
info("Creating PR via Azure DevOps API...");

interface CreatedPR {
  pullRequestId: number;
  url: string;
}

const pr = await ado<CreatedPR>(
  `/git/repositories/${ADO_REPO}/pullRequests?api-version=7.1`,
  {
    method: "POST",
    body: JSON.stringify({
      sourceRefName: `refs/heads/${sourceBranch}`,
      targetRefName: `refs/heads/${targetBranch}`,
      title,
      description,
      isDraft,
    }),
  },
);

// ── Link work item to PR ─────────────────────────────────────
async function linkWorkItemToPr(
  workItemId: number,
  pullRequestId: number,
): Promise<void> {
  const repo = await ado<{ id: string; project: { id: string } }>(
    `/git/repositories/${ADO_REPO}?api-version=7.1`,
  );
  const resource = `vstfs:///Git/PullRequestId/${repo.project.id}/${repo.id}/${pullRequestId}`;
  await ado(`/wit/workitems/${workItemId}/relations?api-version=7.1`, {
    method: "PATCH",
    body: JSON.stringify([
      {
        rel: "Artifact",
        attributes: {
          name: "Pull Request",
          resource,
          resourceName: `Pull Request ${pullRequestId}`,
        },
      },
    ]),
  });
  success(`Linked work item ${workItemId} to PR !${pullRequestId}`);
}

success(`PR !${pr.pullRequestId} created`);

const prUrl = `https://dev.azure.com/${ADO_ORG}/${encodeURIComponent(
  ADO_PROJECT,
)}/_git/${ADO_REPO}/pullrequest/${pr.pullRequestId}`;
console.log(`\n${c.green}${prUrl}${c.reset}\n`);

const workItemId = extractWorkItemId(sourceBranch);
if (workItemId) {
  await linkWorkItemToPr(workItemId, pr.pullRequestId);
}
